	/** 
	 * jumpstart the process by instantiating2 Obligation
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		obligationId = ObligationService.getObligationInstance()
		.createObligation( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		ObligationService.getObligationInstance()
				.createObligation( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.obligationSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Obligation : " + successValue.getObligationId());
							  if (successValue.getObligationId().equals(obligationId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfObligationList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Obligation test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on obligation consumed")
					);
			subscriber.obligationSubscribe( obligationId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Obligation : " + successValue.getObligationId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfObligationList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on obligation for obligationId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Obligation. 
	 */
	protected Obligation read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Obligation" );

		Obligation entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Obligation with primary key" );
		msg.append( obligationId );
		
		ObligationFetchOneSummary fetchOneSummary = new ObligationFetchOneSummary( obligationId );

		try {
			entity = ObligationService.getObligationInstance().getObligation( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Obligation " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Obligation.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Obligation." );

		StringBuilder msg = new StringBuilder( "Failed to update a Obligation : " );        
		Obligation entity = read();
		UpdateObligationCommand command = generateUpdateCommand();
		command.setObligationId(entity.getObligationId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Obligation." );

			// for use later on...
			obligationId = entity.getObligationId();

			ObligationService proxy = ObligationService.getObligationInstance();  

			proxy.updateObligation( command ).get();

			LOGGER.info( "-- Successfully saved Obligation - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + obligationId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Obligation.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Obligation." );

		Obligation entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Obligation with id " + obligationId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Obligation with id " + obligationId );

			throw e;
		}

		try{
			ObligationService.getObligationInstance().delete( new DeleteObligationCommand( entity.getObligationId() ) ).get();
			LOGGER.info( "-- Successfully deleted Obligation with id " + obligationId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Obligation with id " + obligationId );

			throw e;
		}
	}

	/**
	 * get all Obligations.
	 */
	protected List<Obligation> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Obligations:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Obligation : " );        
		List<Obligation> collection  = new ArrayList<>();

		try {
			// call the static get method on the ObligationService
			collection = ObligationService.getObligationInstance().getAllObligation();
			assertNotNull( collection, "An Empty collection of Obligation was incorrectly returned.");
			
			// Now print out the values
			Obligation entity = null;            
			Iterator<Obligation> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getObligationId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

